import bisect


def due_doses(meds, taken, now, tz):
    local_now = now + tz
    day_index = local_now // 1440
    day_start = day_index * 1440
    now_minute = local_now - day_start

    taken_by_med = {}
    for entry in taken:
        at = entry["at"]
        if at > now:
            continue
        at_local = at + tz
        if at_local // 1440 != day_index:
            continue
        minute = at_local - day_start
        taken_by_med.setdefault(entry["med"], []).append(minute)

    due = []
    for med in meds:
        name = med["name"]
        available = sorted(t for t in med.get("times", []) if t <= now_minute)
        if not available:
            continue

        taps = sorted(taken_by_med.get(name, []))
        for tap in taps:
            idx = bisect.bisect_right(available, tap) - 1
            if idx >= 0:
                available.pop(idx)

        for t in available:
            due.append({"med": name, "time": t})

    due.sort(key=lambda d: (d["time"], d["med"]))
    return due


def should_send(sent, event, tz):
    times = [n["t"] for n in sent]
    times.append(event["t"])
    times.sort()

    for i in range(len(times) - 3):
        if times[i + 3] - times[i] < 60:
            return False
    return True


def plan_pushes(meds, taken, sent, now, tz):
    due = due_doses(meds, taken, now, tz)

    local_now = now + tz
    current_day = local_now // 1440

    sent_today_keys = set()
    for entry in sent:
        if (entry["t"] + tz) // 1440 == current_day:
            sent_today_keys.add(entry["key"])

    history = list(sent)
    pushes = []

    for dose in due:
        med = dose["med"]
        time = dose["time"]
        key = f"{med}@{time}"

        if key in sent_today_keys:
            continue

        event = {"key": key, "t": now, "severity": "info"}
        if should_send(history, event, tz):
            pushes.append({"key": key, "med": med, "time": time})
            history.append({"key": key, "t": now})
            sent_today_keys.add(key)

    return pushes
