"""Medication reminder calculation using a fixed UTC offset.

All timestamps are absolute integer minutes. Medication times are minutes
after local midnight. A taken tap is associated with the most recent dose
scheduled at or before the tap's local time on the tap's local day. This
allows a user to mark a dose taken shortly after it was scheduled.

Notification keys are reused each day, so duplicate suppression is scoped to
the event's local day. Both informational and critical events are subject to
the same limit of three notifications in a rolling 60-minute interval.
"""

from collections.abc import Mapping


__all__ = ["due_doses", "should_send", "plan_pushes"]

_MINUTES_PER_DAY = 1440
_NOTIFICATION_LIMIT = 3
_NOTIFICATION_WINDOW = 60
_VALID_SEVERITIES = frozenset(("info", "critical"))


def _require_integer(value, name):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an integer")
    return value


def _require_string(value, name):
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a string")
    return value


def _require_mapping(value, name):
    if not isinstance(value, Mapping):
        raise TypeError(f"{name} must be a mapping")
    return value


def _local_parts(timestamp, tz):
    """Return the local day number and minute within that day."""
    local_timestamp = timestamp + tz
    return local_timestamp // _MINUTES_PER_DAY, local_timestamp % _MINUTES_PER_DAY


def _normalise_schedules(meds):
    """Merge repeated medication names and remove duplicate scheduled times."""
    schedules = []
    positions = {}

    for index, medication in enumerate(meds):
        medication = _require_mapping(medication, f"meds[{index}]")
        name = _require_string(
            medication.get("name"), f"meds[{index}]['name']"
        )
        raw_times = medication.get("times")
        if isinstance(raw_times, (str, bytes)):
            raise TypeError(f"meds[{index}]['times'] must be an iterable of integers")

        try:
            times = list(raw_times)
        except TypeError as exc:
            raise TypeError(
                f"meds[{index}]['times'] must be an iterable of integers"
            ) from exc

        if name not in positions:
            positions[name] = len(schedules)
            schedules.append((name, []))

        schedule = schedules[positions[name]][1]
        for value in times:
            value = _require_integer(value, f"meds[{index}]['times'] entry")
            if not 0 <= value < _MINUTES_PER_DAY:
                raise ValueError(
                    f"meds[{index}]['times'] entries must be between "
                    f"0 and {_MINUTES_PER_DAY - 1}"
                )
            if value not in schedule:
                schedule.append(value)

    return schedules


def _normalise_taken(taken):
    rows = []
    for index, record in enumerate(taken):
        record = _require_mapping(record, f"taken[{index}]")
        medication = _require_string(
            record.get("med"), f"taken[{index}]['med']"
        )
        at = _require_integer(record.get("at"), f"taken[{index}]['at']")
        rows.append((medication, at))
    return rows


def _normalise_sent(sent):
    rows = []
    for index, record in enumerate(sent):
        record = _require_mapping(record, f"sent[{index}]")
        key = _require_string(record.get("key"), f"sent[{index}]['key']")
        at = _require_integer(record.get("t"), f"sent[{index}]['t']")
        rows.append((key, at))
    return rows


def due_doses(meds, taken, now, tz) -> list:
    """Return scheduled doses that are currently due and not marked taken.

    A tap marks the latest scheduled dose for that medication whose local
    time is no later than the tap's local time. Taps from other local days,
    future taps, and taps for unknown medications do not suppress a dose.
    """
    now = _require_integer(now, "now")
    tz = _require_integer(tz, "tz")

    schedules = _normalise_schedules(meds)
    taken_rows = _normalise_taken(taken)
    current_day, current_local_minute = _local_parts(now, tz)

    taps_by_medication = {}
    for medication, at in taken_rows:
        if at > now:
            continue

        tap_day, tap_local_minute = _local_parts(at, tz)
        if tap_day == current_day:
            taps_by_medication.setdefault(medication, []).append(tap_local_minute)

    marked_doses = set()
    for medication, times in schedules:
        for tap_local_minute in taps_by_medication.get(medication, ()):
            eligible_times = [
                scheduled_time
                for scheduled_time in times
                if scheduled_time <= tap_local_minute
            ]
            if eligible_times:
                marked_doses.add((medication, max(eligible_times)))

    result = []
    for medication, times in schedules:
        for scheduled_time in times:
            if (
                scheduled_time <= current_local_minute
                and (medication, scheduled_time) not in marked_doses
            ):
                result.append(
                    {"med": medication, "time": scheduled_time}
                )

    return result


def should_send(sent, event, tz) -> bool:
    """Decide whether a notification may be sent now.

    An event is rejected if its key was already sent on the same local day.
    It is also rejected when three or more notifications were sent during
    the inclusive interval from ``event['t'] - 60`` through ``event['t']``.
    Severity does not bypass the notification limit.
    """
    tz = _require_integer(tz, "tz")
    sent_rows = _normalise_sent(sent)

    event = _require_mapping(event, "event")
    key = _require_string(event.get("key"), "event['key']")
    event_time = _require_integer(event.get("t"), "event['t']")
    severity = _require_string(event.get("severity"), "event['severity']")
    if severity not in _VALID_SEVERITIES:
        raise ValueError("event['severity'] must be 'info' or 'critical'")

    event_day, _ = _local_parts(event_time, tz)

    for sent_key, sent_time in sent_rows:
        if sent_key != key or sent_time > event_time:
            continue
        sent_day, _ = _local_parts(sent_time, tz)
        if sent_day == event_day:
            return False

    recent_count = sum(
        1
        for _, sent_time in sent_rows
        if 0 <= event_time - sent_time <= _NOTIFICATION_WINDOW
    )
    return recent_count < _NOTIFICATION_LIMIT


def plan_pushes(meds, taken, sent, now, tz) -> list:
    """Return the dose reminders that should be pushed at this minute.

    Newly accepted pushes are added to a temporary history while planning,
    so the rolling notification limit also applies to this batch. The
    caller's ``sent`` data is not modified.
    """
    now = _require_integer(now, "now")
    tz = _require_integer(tz, "tz")

    doses = due_doses(meds, taken, now, tz)
    history = _normalise_sent(sent)
    planned = []

    for dose in doses:
        medication = dose["med"]
        scheduled_time = dose["time"]
        key = f"{medication}@{scheduled_time}"
        event = {
            "key": key,
            "t": now,
            "severity": "info",
        }

        if should_send(history, event, tz):
            planned.append(
                {
                    "key": key,
                    "med": medication,
                    "time": scheduled_time,
                }
            )
            history.append((key, now))

    return planned
