"""Medication reminder helpers.

All absolute times are integer minutes from Monday 00:00 UTC.
Local time is UTC + tz, where tz is the person's offset in minutes.
"""

from collections import defaultdict
from typing import Any, Dict, List

DAY = 1440
RATE_WINDOW = 60
MAX_NOTIFICATIONS_PER_WINDOW = 3


def _local_day(utc_minute: int, tz: int) -> int:
    """Return the person's local day number for an absolute UTC minute."""
    return (utc_minute + tz) // DAY


def due_doses(
    meds: List[Dict[str, Any]],
    taken: List[Dict[str, Any]],
    now: int,
    tz: int,
) -> List[Dict[str, Any]]:
    """Return current-day doses that are due now and not yet taken.

    A taken tap for a medication is associated with the scheduled dose whose
    interval contains it: from that dose's scheduled time up to the next
    scheduled time for the same medication.  This keeps a single tap from
    marking multiple doses taken and lets a late tap belong to the next dose
    if it occurs after that next dose's scheduled time.
    """
    local_now = now + tz
    local_day = local_now // DAY
    local_minute = local_now % DAY
    day_start_utc = local_day * DAY - tz

    taken_by_med = defaultdict(list)
    for rec in taken:
        try:
            med = rec["med"]
            at = rec["at"]
        except (KeyError, TypeError):
            continue
        if isinstance(at, int) and at <= now:
            taken_by_med[med].append(at)

    times_by_med = defaultdict(list)
    for entry in meds:
        try:
            name = entry["name"]
            times = entry.get("times", [])
        except (KeyError, TypeError, AttributeError):
            continue
        if not isinstance(times, (list, tuple)):
            continue
        for t in times:
            if isinstance(t, int):
                times_by_med[name].append(t)

    result: List[Dict[str, Any]] = []

    for name, times in times_by_med.items():
        if not times:
            continue

        count_by_time = defaultdict(int)
        for t in times:
            count_by_time[t] += 1

        distinct_times = sorted(count_by_time)
        first_time = distinct_times[0]

        for i, t in enumerate(distinct_times):
            if t > local_minute:
                continue

            due_abs = day_start_utc + t

            if i + 1 < len(distinct_times):
                window_end = day_start_utc + distinct_times[i + 1]
            else:
                # Last dose of the local day: its interval extends until the
                # first dose of the next local day.
                window_end = day_start_utc + DAY + first_time

            taken_count = 0
            for at in taken_by_med.get(name, ()):
                if due_abs <= at < window_end:
                    taken_count += 1

            dose_count = count_by_time[t]
            untaken_count = dose_count - min(dose_count, taken_count)
            for _ in range(untaken_count):
                result.append({"med": name, "time": t})

    result.sort(key=lambda dose: (dose["time"], dose["med"]))
    return result


def should_send(
    sent: List[Dict[str, Any]],
    event: Dict[str, Any],
    tz: int,
) -> bool:
    """Decide whether a notification should be pushed now.

    A notification key is not repeated within the same local day, so a due
    dose does not generate a new push every minute.  Keys may repeat on later
    local days, which matters for daily medication keys such as "med@480".

    The rate limit is at most three notifications in any rolling 60-minute
    window, including the candidate event.
    """
    try:
        key = event["key"]
        event_time = event["t"]
    except (KeyError, TypeError):
        return False

    if not isinstance(event_time, int):
        return False

    event_day = _local_day(event_time, tz)

    for rec in sent:
        try:
            sent_key = rec["key"]
            sent_time = rec["t"]
        except (KeyError, TypeError):
            continue
        if (
            sent_key == key
            and isinstance(sent_time, int)
            and _local_day(sent_time, tz) == event_day
        ):
            return False

    times = []
    for rec in sent:
        try:
            sent_time = rec["t"]
        except (KeyError, TypeError):
            continue
        if isinstance(sent_time, int):
            times.append(sent_time)

    times.append(event_time)
    times.sort()

    # Check every 60-minute window that starts at a notification time.  Any
    # window with more than the allowed count can be shifted left to start at
    # its first notification, so checking these starts is sufficient.
    for i, start in enumerate(times):
        count = 0
        for later in times[i:]:
            if later < start + RATE_WINDOW:
                count += 1
                if count > MAX_NOTIFICATIONS_PER_WINDOW:
                    return False
            else:
                break

    return True


def plan_pushes(
    meds: List[Dict[str, Any]],
    taken: List[Dict[str, Any]],
    sent: List[Dict[str, Any]],
    now: int,
    tz: int,
) -> List[Dict[str, Any]]:
    """Return the medication reminders that should be pushed right now."""
    pushes: List[Dict[str, Any]] = []
    working_sent = list(sent)

    for dose in due_doses(meds, taken, now, tz):
        med = dose["med"]
        time = dose["time"]
        key = f"{med}@{time}"

        event = {"key": key, "t": now, "severity": "info"}

        if should_send(working_sent, event, tz):
            pushes.append({"key": key, "med": med, "time": time})
            working_sent.append({"key": key, "t": now})

    return pushes
